import { assertEquals } from "jsr:@std/assert";
import { World } from "../src/lib/ecs-js/index.js";
import { DungeonState } from "../src/rules/components/DungeonState.js";
import { Player } from "../src/rules/components/Player.js";
import { Score } from "../src/rules/components/Score.js";
import { Vitality } from "../src/rules/components/Vitality.js";
import { installScoreListener } from "../src/rules/systems/scoreSystem.js";
import { DiedEvent } from "../src/shared/events/deathEvents.js";

function setupWorld() {
  const world = new World({ seed: 1 });
  const player = world.create();
  world.add(player, Player);
  world.add(player, Score, { current: 0 });

  const monster = world.create();
  world.add(monster, Vitality, { hp: 0, maxHp: 7 });

  const dungeon = world.create();
  world.add(dungeon, DungeonState, { currentDepth: 3 });

  return { world, player, monster };
}

Deno.test("score listener installs once through world extension guard", () => {
  const { world, player, monster } = setupWorld();
  installScoreListener(world);
  installScoreListener(world);

  world.emit(new DiedEvent({ id: monster, killer: player, cause: "test" }));

  assertEquals(world.get(player, Score).current, 21);
  assertEquals(world.extensions().filter((entry) => entry.name === "jshack:score:kill-listener").length, 1);
});

Deno.test("score listener consumes DiedEvent class, not legacy died string", () => {
  const { world, player, monster } = setupWorld();
  installScoreListener(world);

  world.emit("died", { id: monster, killer: player, cause: "legacy-test" });
  assertEquals(world.get(player, Score).current, 0);

  world.emit(new DiedEvent({ id: monster, killer: player, cause: "class-test" }));
  assertEquals(world.get(player, Score).current, 21);
});

